parameters.jsCode:
const lead = $('Clean Up Form Data').item.json;
const intent = ($json.output) || {};

let existing = {};
try { existing = $('Find Existing Lead').item.json || {}; } catch (e) { existing = {}; }

const hasPriorRecord = Boolean(existing && existing.id);
const isCustomer = hasPriorRecord && String(existing.accountStatus || '').toLowerCase() === 'customer';

// Is there already an open lead from this email in the last 24 hours?
const openStatuses = ['awaiting_ack', 'escalated'];
const priorStatus = String(existing.status || '').toLowerCase();
let hoursSincePrior = 9999;
if (existing.assignedAt) {
  const prior = new Date(existing.assignedAt).getTime();
  if (!isNaN(prior)) { hoursSincePrior = (Date.now() - prior) / 3600000; }
}
const isOpenDuplicate = hasPriorRecord && openStatuses.indexOf(priorStatus) > -1 && hoursSincePrior < 24;

const email = String(lead.email || '').toLowerCase();
const domain = email.indexOf('@') > -1 ? email.split('@')[1] : '';
const freeMail = ['gmail.com','yahoo.com','hotmail.com','outlook.com','aol.com','icloud.com','proton.me','protonmail.com','live.com','msn.com'];
const isCorporate = Boolean(domain) && freeMail.indexOf(domain) === -1;

// Form answers come first; AI-read values only fill gaps.
const propertyType = String(lead.propertyType || intent.propertyType || '').toLowerCase();
const roofType = String(lead.roofType || intent.roofType || '').toLowerCase();
const siteOwnership = String(lead.siteOwnership || intent.siteOwnership || '').toLowerCase();
const monthlyKwh = Number(lead.monthlyKwh || intent.monthlyKwh || 0);
const roofAge = Number(lead.roofAgeYears || 0);

let score = 0;
const reasons = [];

// Building type
if (propertyType.indexOf('industrial') > -1 || propertyType.indexOf('warehouse') > -1 || propertyType.indexOf('manufactur') > -1 || propertyType.indexOf('logistics') > -1) { score += 18; reasons.push("Industrial building"); }
else if (propertyType.indexOf('commercial') > -1 || propertyType.indexOf('office') > -1 || propertyType.indexOf('retail') > -1 || propertyType.indexOf('agricultur') > -1) { score += 15; reasons.push("Commercial building"); }
else if (propertyType.indexOf('residential') > -1 || propertyType.indexOf('home') > -1 || propertyType.indexOf('house') > -1) { score -= 40; reasons.push("Home, not a business (we only do commercial)"); }
else { reasons.push("Building type not given"); }

// Electricity use - the strongest sign of a good fit
if (monthlyKwh >= 50000) { score += 30; reasons.push("Very high electricity use"); }
else if (monthlyKwh >= 20000) { score += 22; reasons.push("High electricity use"); }
else if (monthlyKwh >= 5000) { score += 12; reasons.push("Moderate electricity use"); }
else if (monthlyKwh > 0) { score -= 10; reasons.push("Electricity use too low for solar to pay off"); }
else { reasons.push("Electricity use not given"); }

// Do they own the building?
if (siteOwnership.indexOf('own') > -1) { score += 20; reasons.push("Owns the building"); }
else if (siteOwnership.indexOf('lease') > -1 || siteOwnership.indexOf('tenant') > -1 || siteOwnership.indexOf('rent') > -1) { score += 4; reasons.push("Rents the building (needs landlord OK)"); }
else { reasons.push("Ownership not given"); }

// Roof
if (roofType.indexOf('flat') > -1 || roofType.indexOf('tpo') > -1 || roofType.indexOf('epdm') > -1 || roofType.indexOf('membrane') > -1) { score += 14; reasons.push("Flat roof (good for solar)"); }
else if (roofType.indexOf('metal') > -1 || roofType.indexOf('standing seam') > -1 || roofType.indexOf('trapezoid') > -1) { score += 12; reasons.push("Metal roof (good for solar)"); }
else if (roofType.indexOf('asbestos') > -1) { score -= 25; reasons.push("Asbestos roof (must be dealt with first)"); }
else if (roofType.indexOf('tile') > -1 || roofType.indexOf('shingle') > -1 || roofType.indexOf('slate') > -1) { score -= 8; reasons.push("Tile, shingle or slate roof (harder to install)"); }

if (roofAge > 0 && roofAge <= 10) { score += 8; reasons.push("Roof is fairly new"); }
else if (roofAge >= 20) { score -= 15; reasons.push("Roof is old (may need replacing first)"); }

if (isCorporate) { score += 8; reasons.push("Uses a company email"); }
if (lead.company) { score += 5; reasons.push("Gave a company name"); }

if (intent.budgetSignal === 'stated') { score += 12; reasons.push("Mentioned a budget"); }
else if (intent.budgetSignal === 'implied') { score += 7; reasons.push("Hinted at a budget"); }

if (intent.urgency === 'high') { score += 10; reasons.push("Wants to move quickly"); }
else if (intent.urgency === 'medium') { score += 5; }

const nonSalesIntents = ['maintenance_existing', 'supplier_pitch', 'job_application', 'spam'];
const isNonSales = nonSalesIntents.indexOf(String(intent.intent || '')) > -1;

if (intent.intent === 'quote_request' || intent.intent === 'site_assessment') { score += 18; reasons.push("Asked for a quote or site visit"); }
if (intent.intent === 'financing_enquiry') { score += 12; reasons.push("Asked about financing"); }
if (isNonSales) { score -= 50; reasons.push("Not a sales enquiry"); }

const conf = Number(intent.confidence || 0);
if (conf > 0 && conf < 0.5) { score -= 10; reasons.push("Message is unclear"); }
if (!intent.intent) { score -= 15; reasons.push("AI could not read the message"); }

if (score < 0) { score = 0; }
if (score > 100) { score = 100; }

// Lead type - order matters
let tier = 'nurture';
if (isOpenDuplicate) { tier = 'duplicate'; reasons.push("Already an open lead from this email"); }
else if (isNonSales) { tier = 'nurture'; }
else if (isCustomer) { tier = 'existing_customer'; reasons.push("Existing customer"); }
else if (score >= 65) { tier = 'enterprise'; }
else if (score >= 35) { tier = 'smb'; }

const tierLabels = { existing_customer: 'Existing customer', enterprise: 'Large business', smb: 'Small business', nurture: 'Low priority', duplicate: 'Duplicate' };
const intentLabels = { quote_request: 'Wants a quote', site_assessment: 'Wants a site visit', financing_enquiry: 'Asking about financing', general_enquiry: 'General question', maintenance_existing: 'Support for existing system', supplier_pitch: 'Supplier pitch', job_application: 'Job application', spam: 'Spam' };

// Rough system size for the rep only - NOT a quote.
// Assumes about 1300 kWh produced per kW of panels per year.
let estKw = 0;
if (monthlyKwh > 0) { estKw = Math.round((monthlyKwh * 12) / 1300); }

// Follow-up deadline: 15 minutes, counted in business hours only
// (Mon-Fri 08:00-18:00, workflow timezone). A lead that arrives overnight or
// at the weekend is due at 08:15 on the next business morning instead of
// being escalated to the manager before anyone is at work.
const OPEN_HOUR = 8;
const CLOSE_HOUR = 18;
const inHours = (d) => d.weekday <= 5 && d.hour >= OPEN_HOUR && d.hour < CLOSE_HOUR;
let clockStart = $now;
if (!inHours(clockStart)) {
  if (clockStart.weekday > 5 || clockStart.hour >= CLOSE_HOUR) { clockStart = clockStart.plus({ days: 1 }); }
  clockStart = clockStart.set({ hour: OPEN_HOUR, minute: 0, second: 0, millisecond: 0 });
  while (clockStart.weekday > 5) { clockStart = clockStart.plus({ days: 1 }); }
}
const ackDue = clockStart.plus({ minutes: 15 });

return {
  json: {
    name: lead.name,
    email: lead.email,
    phone: lead.phone,
    company: lead.company || '',
    message: lead.message,
    source: lead.source,
    country: String(lead.country || '').toLowerCase(),
    consent: Boolean(lead.consent),
    receivedAt: lead.receivedAt,
    executionId: lead.executionId,
    hasPriorRecord: hasPriorRecord,
    isCustomer: isCustomer,
    isOpenDuplicate: isOpenDuplicate,
    priorStatus: priorStatus,
    existingRecordId: existing.id || '',
    propertyType: propertyType,
    roofType: roofType,
    siteOwnership: siteOwnership,
    monthlyKwh: monthlyKwh,
    roofAgeYears: roofAge,
    utilityProvider: lead.utilityProvider || '',
    estimatedSystemKw: estKw,
    intent: intent.intent || 'unknown',
    intentLabel: intentLabels[intent.intent] || 'Unknown',
    urgency: intent.urgency || 'unknown',
    budgetSignal: intent.budgetSignal || 'none',
    painPoint: intent.painPoint || '',
    requestedProduct: 'commercial rooftop solar',
    intentConfidence: conf,
    score: score,
    tier: tier,
    tierLabel: tierLabels[tier] || tier,
    reasons: reasons,
    ackDueAt: ackDue.toUTC().toISO(),
    ackDueLocal: ackDue.toFormat('ccc d LLL, HH:mm'),
    receivedAfterHours: !inHours($now)
  }
};

